"""Money and journal-leg value types."""
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN
import re

CURRENCY_RE = re.compile(r"^[A-Z]{3}$")
CENTS = Decimal("0.01")


def as_decimal(value):
    """Convert a supported numeric value to a finite Decimal."""
    try:
        if isinstance(value, bool) or not isinstance(value, (Decimal, int, str, float)):
            raise ValueError("boolean amount")
        result = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ValueError("invalid decimal") from exc
    if not result.is_finite():
        raise ValueError("expected finite value")
    return result


def check_currency(code):
    if not isinstance(code, str) or CURRENCY_RE.fullmatch(code) is None:
        raise ValueError(f"invalid currency code: {code!r}")
    return code


def quantize(amount):
    """Round to cents."""
    return as_decimal(amount).quantize(CENTS, rounding=ROUND_HALF_EVEN)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str

    def __post_init__(self):
        object.__setattr__(self, "amount", as_decimal(self.amount))
        check_currency(self.currency)

    def add(self, other):
        if not isinstance(other, Money) or self.currency != other.currency:
            raise ValueError("money currencies must match")
        return Money(quantize(self.amount + other.amount), self.currency)

    def subtract(self, other):
        if not isinstance(other, Money) or self.currency != other.currency:
            raise ValueError("money currencies must match")
        return Money(quantize(self.amount - other.amount), self.currency)

    def negate(self):
        return Money(-self.amount, self.currency)


@dataclass(frozen=True)
class Leg:
    account: str
    money: Money

    def __post_init__(self):
        if not isinstance(self.account, str) or not self.account:
            raise ValueError("account must be a nonempty string")
        if not isinstance(self.money, Money):
            raise ValueError("money must be a Money instance")
"""Foreign-exchange rate table."""
from datetime import datetime

from models import Money, as_decimal, check_currency, quantize


class RateTable:
    """Point-in-time FX quotes: (base, quote, effective_at) -> rate."""

    def __init__(self):
        self._quotes = {}

    def set_rate(self, base, quote, effective_at, rate):
        check_currency(base)
        check_currency(quote)
        if base == quote:
            raise ValueError("base and quote currencies must differ")
        if not _is_aware(effective_at):
            raise ValueError("effective_at must be timezone-aware")
        value = as_decimal(rate)
        if value <= 0:
            raise ValueError("rate must be positive")
        self._quotes.setdefault((base, quote), []).append((effective_at, value))

    def rate(self, base, quote, at):
        """Latest rate for the pair; KeyError when none exist."""
        check_currency(base)
        check_currency(quote)
        if base == quote:
            return as_decimal(1)
        if not _is_aware(at):
            raise ValueError("at must be timezone-aware")
        eligible = [entry for entry in self._quotes.get((base, quote), ())
                    if entry[0] <= at]
        if not eligible:
            raise KeyError(f"no rate {base}/{quote}")
        return max(eligible, key=lambda entry: entry[0])[1]

    def convert(self, money, target, at):
        """Convert a Money into `target` currency."""
        if not isinstance(money, Money):
            raise ValueError("money must be a Money instance")
        check_currency(target)
        if money.currency == target:
            return Money(quantize(money.amount), target)
        return Money(quantize(money.amount * self.rate(money.currency, target, at)), target)


def _is_aware(value):
    return (isinstance(value, datetime) and value.tzinfo is not None
            and value.utcoffset() is not None)
"""Multi-leg journal ledger."""
from collections import OrderedDict
from decimal import Decimal

from models import Leg, Money, check_currency


class Ledger:
    """Append-only journal."""

    def __init__(self):
        self._entries = OrderedDict()

    def post(self, entry_id, legs):
        """Store a journal entry; returns its legs."""
        if not isinstance(entry_id, str) or not entry_id:
            raise ValueError("entry_id must be a nonempty string")
        if entry_id in self._entries:
            raise ValueError("entry_id must be unique")
        try:
            legs = tuple(legs)
        except TypeError as exc:
            raise ValueError("legs must be iterable") from exc
        if len(legs) < 2:
            raise ValueError("journal entry requires at least two legs")
        for leg in legs:
            if not isinstance(leg, Leg):
                raise ValueError("legs must be Leg instances")
        totals = {}
        for leg in legs:
            code = leg.money.currency
            totals[code] = totals.get(code, Decimal(0)) + leg.money.amount
        if any(total != 0 for total in totals.values()):
            raise ValueError("journal entry must balance per currency")
        self._entries[entry_id] = legs
        return legs

    def entries(self):
        yield from self._entries.items()

    def balance(self, account, currency=None):
        totals = {}
        for legs in self._entries.values():
            for leg in legs:
                if leg.account == account:
                    key = leg.money.currency
                    totals[key] = totals.get(key, Decimal(0)) + leg.money.amount
        if currency is not None:
            check_currency(currency)
            return Money(totals.get(currency, Decimal(0)), currency)
        return {code: Money(totals[code], code) for code in sorted(totals)}

    def accounts(self):
        seen = []
        for legs in self._entries.values():
            for leg in legs:
                if leg.account not in seen:
                    seen.append(leg.account)
        return seen
"""Ledger-vs-expected reconciliation."""
from dataclasses import dataclass
from decimal import Decimal

from models import Money, as_decimal, check_currency, quantize


@dataclass(frozen=True)
class Discrepancy:
    account: str
    currency: str
    expected: Decimal
    actual: Decimal
    difference: Decimal


class Reconciler:
    def __init__(self, ledger, rates):
        self.ledger = ledger
        self.rates = rates

    def trial_balance(self, account, target, at):
        check_currency(target)
        total = Decimal(0)
        for _, legs in self.ledger.entries():
            for leg in legs:
                if leg.account == account:
                    total += self.rates.convert(leg.money, target, at).amount
        return Money(quantize(total), target)

    def reconcile(self, expected, at):
        expected_values = {}
        for key, amount in expected.items():
            if (not isinstance(key, tuple) or len(key) != 2):
                raise ValueError("expected keys must be (account, currency) pairs")
            account, currency = key
            if not isinstance(account, str) or not account:
                raise ValueError("account must be a nonempty string")
            check_currency(currency)
            expected_values[(account, currency)] = quantize(as_decimal(amount))

        actual_values = {}
        for _, legs in self.ledger.entries():
            for leg in legs:
                key = (leg.account, leg.money.currency)
                actual_values[key] = actual_values.get(key, Decimal(0)) + leg.money.amount
        actual_values = {key: quantize(amount) for key, amount in actual_values.items()}

        discrepancies = []
        for account, currency in sorted(set(expected_values) | set(actual_values)):
            want = expected_values.get((account, currency), Decimal(0))
            have = actual_values.get((account, currency), Decimal(0))
            if want != have:
                discrepancies.append(Discrepancy(
                    account, currency, want, have, quantize(have - want)))
        return discrepancies
